class FrontMiddleBackQueue {
    private java.util.Deque<Integer> first = new java.util.ArrayDeque<>();
    private java.util.Deque<Integer> second = new java.util.ArrayDeque<>();
    public FrontMiddleBackQueue() {}
    private void balance() {
        if (first.size() > second.size()) second.addFirst(first.pollLast());
        if (second.size() > first.size() + 1) first.addLast(second.pollFirst());
    }
    public void pushFront(int val) { first.addFirst(val); balance(); }
    public void pushMiddle(int val) { first.addLast(val); balance(); }
    public void pushBack(int val) { second.addLast(val); balance(); }
    public int popFront() {
        if (second.isEmpty()) return -1;
        int val = first.isEmpty() ? second.pollFirst() : first.pollFirst();
        balance(); return val;
    }
    public int popMiddle() {
        if (second.isEmpty()) return -1;
        int val = first.size() == second.size() ? first.pollLast() : second.pollFirst();
        balance(); return val;
    }
    public int popBack() {
        if (second.isEmpty()) return -1;
        int val = second.pollLast(); balance(); return val;
    }
}

import java.util.*;

class FrontMiddleBackQueue {
    private List<Integer> list;
    public FrontMiddleBackQueue() {
        list = new ArrayList();
    }
    public void pushFront(int val) {
        list.add(0, val);
    }
    public void pushMiddle(int val) {
        list.add(list.size() / 2, val);
    }
    public void pushBack(int val) {
        list.add(val);
    }
    public int popFront() {
        if (list.isEmpty()) return -1;
        return list.remove(0).intValue();
    }
    public int popMiddle() {
        if (list.isEmpty()) return -1;
        int mid = (list.size() - 1) / 2;
        return list.remove(mid).intValue();
    }
    public int popBack() {
        if (list.isEmpty()) return -1;
        return list.remove(list.size() - 1).intValue();
    }
}
